import { useGetMedia } from "@/src/lib/ReactQuery/query/admin/media/query"

export default function MediaPage() {
    const mediaGet = useGetMedia();
    return<main>
        <h3>Медиатека</h3>
        <section>
            {mediaGet.isLoading && <p>Загрузка...</p>}
            {mediaGet.data && mediaGet.data.length > 0 && mediaGet.data.map((media) => {

                return <div>{media}</div>
            })}
        </section>

    </main>
}